### ⚙️ 2. Serviço de Patch (PatchService)

Este serviço será o coração da sua aplicação. Ele lida com I/O, rede e o estado do download.

**Nota Importante sobre Lua:** Arquivos `.lua` usam uma sintaxe que não é nativamente deserializável por `System.Text.Json` (que usa JSON). O método mais robusto seria usar uma biblioteca Lua.NET, mas para simplificar e manter o código Blazor "puro", farei o tratamento de leitura assumindo que podemos **simplesmente adaptar o formato para JSON**, ou farei uma lógica de leitura de texto e manipulação de strings para extrair os dados.

Vou optar por uma simulação de parsing, mas você deve estar ciente de que um parser Lua completo é necessário para um ambiente de produção.

**`PatchService.cs`**

```csharp
using System.Net.Http.Headers;
using System.Security.Cryptography;

public class PatchService
{
    private readonly HttpClient _httpClient;
    private readonly string _patchDirectory = Path.Combine(AppContext.BaseDirectory, "patch");
    private readonly string _luaFilePath = "patch.lua";

    // Estado que será consumido pelo componente UI
    public event Action<PatchState> OnStateChanged;

    public PatchService(HttpClient httpClient)
    {
        _httpClient = httpClient;
        Directory.CreateDirectory(_patchDirectory); // Garante que a pasta existe
    }

    // --- ESTADOS DE TRABALHO ---
    public class PatchState
    {
        public string StatusMessage { get; set; } = "Iniciando...";
        public int CurrentFileIndex { get; set; } = 0;
        public List<UpdateItem> Manifest { get; set; } = new List<UpdateItem>();
        public double ProgressPercent { get; set; } = 0;
        public bool IsDownloading { get; set; } = false;
        public string CurrentFileName { get; set; } = string.Empty;
        public string CurrentHashValue { get; set; } = string.Empty;
    }

    private PatchState _currentState = new PatchState();
    public PatchState CurrentState => _currentState;

    private void NotifyStateChanged() => OnStateChanged?.Invoke(_currentState);

    // -----------------------------------------------------------------
    // ETAPA 1 & 2: Iniciar e Autenticar
    // -----------------------------------------------------------------
    public async Task StartPatchingAsync()
    {
        _currentState.IsDownloading = true;
        _currentState.StatusMessage = "Conectando ao servidor...";
        NotifyStateChanged();

        // 1. Leitura e Parsing do Patch (Simulando a leitura do Lua)
        var manifest = await LoadManifestAsync();
        _currentState.Manifest = manifest;

        if (!manifest.Updates.Any())
        {
            _currentState.StatusMessage = "Erro: Manifest vazio.";
            _currentState.IsDownloading = false;
            NotifyStateChanged();
            return;
        }

        _currentState.StatusMessage = "Autenticando o servidor...";
        // Aqui você implementaria o código de autenticação (ex: request de token)
        await Task.Delay(1000); // Simulação de autenticação
        _currentState.StatusMessage = "Preparando para iniciar o download...";
        NotifyStateChanged();

        // 2. Iniciar o download dos arquivos
        await DownloadUpdatesAsync();
    }

    // Lógica de leitura e parsing do arquivo .lua
    private async Task<PatchManifest> LoadManifestAsync()
    {
        try
        {
            // !!! ATENÇÃO: A leitura de Lua exige um parser.
            // Esta função simula a leitura, assumindo que o conteúdo pode ser parseado
            // ou que você o converteu para JSON.
            // Para este exemplo, usaremos dados de fallback, mas você DEVE implementar o parser.
            string luaContent = await File.ReadAllTextAsync(_luaFilePath);

            // *** Se você estiver usando uma biblioteca de terceiros de Lua.NET,
            // *** você faria o parsing aqui.

            // SIMULAÇÃO de Parsing (Baseada nos dados que você forneceu)
            var manifest = new PatchManifest();
            manifest.Updates.Add(new UpdateItem 
            { Version = 1, FileName = "100MB.bin", Integrity = "741sa871sa5871sa", DownloadUrl = "https://hil-speed.hetzner.com/100MB.bin" });
            manifest.Updates.Add(new UpdateItem 
            { Version = 2, FileName = "1GB.bin", Integrity = "741sa871sa5871sa", DownloadUrl = "https://hil-speed.hetzner.com/1GB.bin" });
            manifest.Updates.Add(new UpdateItem 
            { Version = 3, FileName = "10GB.bin", Integrity = "741sa871sa5871sa", DownloadUrl = "https://hil-speed.hetzner.com/10GB.bin" });
            manifest.Updates.Add(new UpdateItem 
            { Version = 4, FileName = "test.rgz", Integrity = "741sa871sa5871sa", DownloadUrl = "https://hil-speed.hetzner.com/test.rgz" });

            return manifest;

        }
        catch (FileNotFoundException)
        {
            _currentState.StatusMessage = $"Erro: Arquivo de manifest ({_luaFilePath}) não encontrado.";
            _currentState.IsDownloading = false;
            NotifyStateChanged();
            return new PatchManifest();
        }
        catch (HttpRequestException ex) when (ex.Message.Contains("404"))
        {
            // Tratar erro de arquivo não encontrado no manifesto (não no download)
            _currentState.StatusMessage = "Erro: Arquivo de manifesto 404.";
            _currentState.IsDownloading = false;
            NotifyStateChanged();
            return new PatchManifest();
        }
        catch (Exception ex)
        {
            _currentState.StatusMessage = $"Erro ao carregar o manifest: {ex.Message}";
            _currentState.IsDownloading = false;
            NotifyStateChanged();
            return new PatchManifest();
        }
    }

    // -----------------------------------------------------------------
    // ETAPA 3-5: Processamento dos Downloads
    // -----------------------------------------------------------------
    private async Task DownloadUpdatesAsync()
    {
        int totalFiles = _currentState.Manifest.Updates.Count;
        int completedFiles = 0;
        int retryCount = 0;

        while (completedFiles < totalFiles)
        {
            UpdateItem currentItem = _currentState.Manifest.Updates[retryCount % totalFiles];
            _currentState.CurrentFileIndex = retryCount;
            _currentState.CurrentFileName = currentItem.FileName;
            _currentState.CurrentHashValue = currentItem.Integrity;

            // ETAPA 5: Checar se o arquivo já existe
            string fullPath = Path.Combine(_patchDirectory, currentItem.FileName);
            if (File.Exists(fullPath))
            {
                _currentState.StatusMessage = "O arquivo já existe, verificando se é necessário fazer download...";

                // Verificação de Integridade (Hash)
                try
                {
                    string fileHash = await CalculateFileHashAsync(fullPath);
                    if (fileHash.Equals(currentItem.Integrity, StringComparison.OrdinalIgnoreCase))
                    {
                        _currentState.StatusMessage = $"Arquivo {currentItem.FileName} OK. Pulando.";
                        completedFiles++;
                        await Task.Delay(500);
                        continue; // Passa para o próximo item
                    }
                    else
                    {
                        _currentState.StatusMessage = "Hash diferente. Necessário fazer download...";
                        // Se o hash for diferente, resetamos o contador de retries e continuamos o download
                        retryCount = 0; 
                        await Task.Delay(500);
                        continue;
                    }
                }
                catch (Exception ex)
                {
                    _currentState.StatusMessage = $"Erro ao calcular hash de {currentItem.FileName}: {ex.Message}. Tentando baixar.";
                    // Se não conseguir calcular o hash, forçamos o download.
                }
            }

            // Iniciar o download
            await TryDownloadFileAsync(currentItem, fullPath);

            // Se o download foi bem-sucedido, contamos como concluído
            completedFiles++;
            retryCount = 0; 

            // Atualiza o progresso geral do processo
            _currentState.ProgressPercent = (double)completedFiles / totalFiles * 100;
            NotifyStateChanged();
        }

        // FINALIZAÇÃO
        _currentState.StatusMessage = "✅ Processo de patch concluído com sucesso!";
        _currentState.IsDownloading = false;
        _currentState.ProgressPercent = 100;
        NotifyStateChanged();
    }

    // Função que encapsula a tentativa de download e tratamento de erros
    private async Task TryDownloadFileAsync(UpdateItem item, string fullPath)
    {
        int maxRetries = 5;
        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                _currentState.StatusMessage = attempt > 0 
                    ? "Reiniciando o download... (Tentativa " + (attempt + 1) + ")" 
                    : $"Baixando arquivo ({item.FileName})...";

                // ETAPA 4: Continuar de onde parou (Resumable Download)
                long existingLength = 0;
                if (File.Exists(fullPath))
                {
                    existingLength = new FileInfo(fullPath).Length;
                }

                var request = new HttpRequestMessage(HttpMethod.Get, item.DownloadUrl);

                // Define o Range header para retomar o download
                if (existingLength > 0)
                {
                    request.Headers.Range = new RangeHeaderValue(existingLength, null);
                    _currentState.StatusMessage = $"[RESUMING] Arquivo existente. Retomando download de {existingLength / 1024 / 1024} MB...";
                }

                using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);

                if (response.IsSuccessStatusCode)
                {
                    // Se o status for 206 (Partial Content), o download está sendo retomado.
                    // Se for 200, é um download novo.

                    await DownloadStreamAsync(response.Content.ReadAsStream(CancellationToken.None), fullPath, existingLength);
                    _currentState.StatusMessage = $"Sucesso: {item.FileName} baixado.";
                    return; // Sai do loop de retries
                }
                else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
                {
                     // ETAPA 3: Arquivo não encontrado
                    _currentState.StatusMessage = $"Erro: Arquivo '{item.FileName}' não encontrado (404). Pulando em 5 segundos...";
                    await Task.Delay(5000);
                    return; // Não tenta novamente se o servidor diz que não existe.
                }
                else
                {
                    // Tratamento de erros de servidor (403, 503, etc.)
                    _currentState.StatusMessage = $"Erro de Servidor {response.StatusCode} ao baixar {item.FileName}.";
                    await Task.Delay(1000 * (attempt + 1)); // Espera mais tempo em falhas graves
                }
            }
            catch (HttpRequestException ex)
            {
                // ETAPA 4: Internet caiu ou conexão perdida
                _currentState.StatusMessage = $"Conexão perdida. {ex.Message}. Tentando reconectar...";
                await Task.Delay(2000);
            }
            catch (Exception ex)
            {
                _currentState.StatusMessage = $"Erro inesperado durante o download: {ex.Message}";
                break; // Para em caso de erro fatal
            }
        }

        _currentState.StatusMessage = $"🚨 Falha crítica ao baixar {item.FileName} após {maxRetries} tentativas.";
    }

    // Método que escreve o stream no disco
    private async Task DownloadStreamAsync(Stream contentStream, string fullPath, long startPosition)
    {
        using var fileStream = new FileStream(fullPath, FileMode.OpenOrCreate, FileAccess.Write, FileShare.None, 8192, useAsync: true);

        if (startPosition > 0)
        {
            // Move o ponteiro para o final do arquivo existente
            fileStream.Seek(startPosition, SeekOrigin.Begin);
        }

        await contentStream.CopyToAsync(fileStream);
    }

    // Calcula o hash SHA256 do arquivo (para checagem de integridade)
    private async Task<string> CalculateFileHashAsync(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = File.OpenRead(filePath);
        var hashBytes = await sha256.ComputeHashAsync(stream);

        // Converte os bytes para uma string hexadecimal
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}
```

### 🎨 3. Componente Blazor (PatchComponent.razor)

Agora vamos traduzir o seu código HTML/Tailwind para um componente Blazor e usar o `PatchService` para preencher os dados dinamicamente.

**Pré-requisitos:** Certifique-se de ter o Tailwind CSS configurado no seu projeto Blazor (ou substitua pelas classes CSS padrão do Bootstrap/etc.).

**`PatchComponent.razor`**

```razor
@using System.Threading.Tasks
@inject PatchService Service
@implements IDisposable

<div class="p-4 bg-gray-800 min-h-screen">
    <h1 class="text-2xl text-white mb-6">Gerenciador de Patch</h1>

    @* --- Área de Controle --- *@
    <button @onclick="StartDownload" class="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded transition duration-150">
        @if (Service.CurrentState.IsDownloading) { <text>Processando...</text> } else { <text>Iniciar Patch</text> }
    </button>

    <hr class="my-6 border-gray-700" />

    @* --- Área de Status (Seu HTML adaptado) --- *@

    @if (Service.CurrentState.Manifest.Any())
    {
        <div class="mt-8 p-4 border border-gray-600 bg-gray-900 rounded-lg shadow-xl">

            @* Status Message Area *@
            <p class="text-[14px] font-bold text-opacity-[0.95] text-white text-center mb-3">
                @Service.CurrentState.StatusMessage
            </p>

            @* Progress Bar Area *@
            <div class="w-[95%] bg-[#0E1622]/[0.95] rounded-md h-5 flex items-center mt-4">
                <div class="bg-[#1164CA]/[0.95] rounded-md h-4 transition-all duration-300" 
                     style="width: @Service.CurrentState.ProgressPercent%"/>
            </div>

            @* Informações Adicionais (Nome/Bytes) *@
            <div class="mt-4 text-sm text-gray-400 flex justify-between">
                <span>Arquivo Atual: @Service.CurrentState.CurrentFileName</span>
                <span>Progresso Geral: @Service.CurrentState.ProgressPercent.ToString("F1")%</span>
            </div>
        </div>
    }
    else if (!Service.CurrentState.Manifest.Any() && Service.CurrentState.StatusMessage.Contains("Manifest"))
    {
         <div class="p-4 bg-red-800 text-white rounded-lg">
             @Service.CurrentState.StatusMessage
         </div>
    }
</div>


@code {
    protected override void OnInitialized()
    {
        // Subscreve ao evento de mudança de estado do serviço
        Service.OnStateChanged += HandleStateChange;
    }

    private void HandleStateChange(PatchService.PatchState newState)
    {
        // Chamar StateHasChanged() força o Blazor a renderizar novamente a UI
        InvokeAsync(() =>
        {
            // Atualiza as propriedades do componente com o novo estado
            // (Embora aqui estejamos usando @inject, o ideal seria injetar os estados)
            // Simplesmente chamamos StateHasChanged() para garantir a atualização.
            StateHasChanged(); 
        });
    }

    private async Task StartDownload()
    {
        if (!Service.CurrentState.IsDownloading)
        {
            await Service.StartPatchingAsync();
        }
    }

    public void Dispose()
    {
        // Limpeza: Garante que a assinatura do evento seja removida quando o componente for destruído
        Service.OnStateChanged -= HandleStateChange;
    }
}
