    // -----------------------------------------------------------------
    // ETAPA 3-5: Processamento dos Downloads
    // -----------------------------------------------------------------
    private async Task DownloadUpdatesAsync()
    {
        int totalFiles = _currentState.Manifest.Updates.Count;
        int completedFiles = 0;
        int retryCount = 0;

        while (completedFiles < totalFiles)
        {
            UpdateItem currentItem = _currentState.Manifest.Updates[retryCount % totalFiles];
            _currentState.CurrentFileIndex = retryCount;
            _currentState.CurrentFileName = currentItem.FileName;
            _currentState.CurrentHashValue = currentItem.Integrity;

            // ETAPA 5: Checar se o arquivo já existe
            string fullPath = Path.Combine(_patchDirectory, currentItem.FileName);
            if (File.Exists(fullPath))
            {
                _currentState.StatusMessage = "O arquivo já existe, verificando se é necessário fazer download...";

                // Verificação de Integridade (Hash)
                try
                {
                    string fileHash = await CalculateFileHashAsync(fullPath);
                    if (fileHash.Equals(currentItem.Integrity, StringComparison.OrdinalIgnoreCase))
                    {
                        _currentState.StatusMessage = $"Arquivo {currentItem.FileName} OK. Pulando.";
                        completedFiles++;
                        await Task.Delay(500);
                        continue; // Passa para o próximo item
                    }
                    else
                    {
                        _currentState.StatusMessage = "Hash diferente. Necessário fazer download...";
                        // Se o hash for diferente, resetamos o contador de retries e continuamos o download
                        retryCount = 0; 
                        await Task.Delay(500);
                        continue;
                    }
                }
                catch (Exception ex)
                {
                    _currentState.StatusMessage = $"Erro ao calcular hash de {currentItem.FileName}: {ex.Message}. Tentando baixar.";
                    // Se não conseguir calcular o hash, forçamos o download.
                }
            }

            // Iniciar o download
            await TryDownloadFileAsync(currentItem, fullPath);

            // Se o download foi bem-sucedido, contamos como concluído
            completedFiles++;
            retryCount = 0; 

            // Atualiza o progresso geral do processo
            _currentState.ProgressPercent = (double)completedFiles / totalFiles * 100;
            NotifyStateChanged();
        }

        // FINALIZAÇÃO
        _currentState.StatusMessage = "✅ Processo de patch concluído com sucesso!";
        _currentState.IsDownloading = false;
        _currentState.ProgressPercent = 100;
        NotifyStateChanged();
    }

    // Função que encapsula a tentativa de download e tratamento de erros
    private async Task TryDownloadFileAsync(UpdateItem item, string fullPath)
    {
        int maxRetries = 5;
        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                _currentState.StatusMessage = attempt > 0 
                    ? "Reiniciando o download... (Tentativa " + (attempt + 1) + ")" 
                    : $"Baixando arquivo ({item.FileName})...";

                // ETAPA 4: Continuar de onde parou (Resumable Download)
                long existingLength = 0;
                if (File.Exists(fullPath))
                {
                    existingLength = new FileInfo(fullPath).Length;
                }

                var request = new HttpRequestMessage(HttpMethod.Get, item.DownloadUrl);

                // Define o Range header para retomar o download
                if (existingLength > 0)
                {
                    request.Headers.Range = new RangeHeaderValue(existingLength, null);
                    _currentState.StatusMessage = $"[RESUMING] Arquivo existente. Retomando download de {existingLength / 1024 / 1024} MB...";
                }

                using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);

                if (response.IsSuccessStatusCode)
                {
                    // Se o status for 206 (Partial Content), o download está sendo retomado.
                    // Se for 200, é um download novo.

                    await DownloadStreamAsync(response.Content.ReadAsStream(CancellationToken.None), fullPath, existingLength);
                    _currentState.StatusMessage = $"Sucesso: {item.FileName} baixado.";
                    return; // Sai do loop de retries
                }
                else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
                {
                     // ETAPA 3: Arquivo não encontrado
                    _currentState.StatusMessage = $"Erro: Arquivo '{item.FileName}' não encontrado (404). Pulando em 5 segundos...";
                    await Task.Delay(5000);
                    return; // Não tenta novamente se o servidor diz que não existe.
                }
                else
                {
                    // Tratamento de erros de servidor (403, 503, etc.)
                    _currentState.StatusMessage = $"Erro de Servidor {response.StatusCode} ao baixar {item.FileName}.";
                    await Task.Delay(1000 * (attempt + 1)); // Espera mais tempo em falhas graves
                }
            }
            catch (HttpRequestException ex)
            {
                // ETAPA 4: Internet caiu ou conexão perdida
                _currentState.StatusMessage = $"Conexão perdida. {ex.Message}. Tentando reconectar...";
                await Task.Delay(2000);
            }
            catch (Exception ex)
            {
                _currentState.StatusMessage = $"Erro inesperado durante o download: {ex.Message}";
                break; // Para em caso de erro fatal
            }
        }

        _currentState.StatusMessage = $"🚨 Falha crítica ao baixar {item.FileName} após {maxRetries} tentativas.";
    }

    // Método que escreve o stream no disco
    private async Task DownloadStreamAsync(Stream contentStream, string fullPath, long startPosition)
    {
        using var fileStream = new FileStream(fullPath, FileMode.OpenOrCreate, FileAccess.Write, FileShare.None, 8192, useAsync: true);

        if (startPosition > 0)
        {
            // Move o ponteiro para o final do arquivo existente
            fileStream.Seek(startPosition, SeekOrigin.Begin);
        }

        await contentStream.CopyToAsync(fileStream);
    }

    // Calcula o hash SHA256 do arquivo (para checagem de integridade)
    private async Task<string> CalculateFileHashAsync(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = File.OpenRead(filePath);
        var hashBytes = await sha256.ComputeHashAsync(stream);

        // Converte os bytes para uma string hexadecimal
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}
